/bin/zsh -lc "python3 - <<'PY'
import random, math
homes=[((0,0),(3,1,2),0),((4,0),(2,3,1),1),((0,3),(1,3,2),1),((4,3),(2,1,3),2),((2,1),(3,2,2),0),((2,3),(2,2,3),2)]
services=[(3,2,(2,0,0)),(4,2,(0,2,0)),(3,2,(0,0,2)),(2,1,(1,0,1)),(3,2,(0,1,1))]
lots=[(x,y) for x in range(5) for y in range(4) if (x,y) not in [h[0] for h in homes]]
def scores(b,heard):
    ret=[]
    for i,(p,need,pri) in enumerate(homes):
        power=[int(i in heard and j==pri) for j in range(3)]
        for pos,(kind,level) in b.items():
            cost,radius,effect=services[kind]
            if abs(p[0]-pos[0])+abs(p[1]-pos[1])<=radius:
                power=[power[j]+(effect[j]+level-1 if effect[j] else 0) for j in range(3)]
        ret.append(sum(min(1,power[j]/need[j]) for j in range(3))/3)
    return ret
def objective(s):
    return sum(min(.72,v) for v in s)+min(s)*1.2+sum(min(1,v) for v in s)*.13
best=(0,None)
random.seed(18)
for attempt in range(800):
    b={};heard=set();money=7;log=[]
    for week in range(1,7):
        if week>1: money+=4
        for action in range(3):
            candidates=[]
            old=objective(scores(b,heard))
            for i in range(6):
                if i not in heard:
                    val=objective(scores(b,heard|{i}))-old+.07
                    candidates.append((val*random.uniform(.7,1.3),('listen',i),b,heard|{i},money+1))
            for pos in lots:
                for typ,(cost,_,_) in enumerate(services):
                    if pos in b or money<cost: continue
                    nb={**b,pos:(typ,1)}
                    val=objective(scores(nb,heard))-old
                    candidates.append(((val/max(1,cost)**.3)*random.uniform(.7,1.3),('build',pos,typ),nb,heard,money-cost))
                if pos in b and b[pos][1]==1 and money>=2:
                    nb={**b,pos:(b[pos][0],2)}
                    val=objective(scores(nb,heard))-old
                    candidates.append(((val/2**.3)*random.uniform(.7,1.3),('upgrade',pos),nb,heard,money-2))
            if candidates:
                _,choice,b,heard,money=max(candidates,key=lambda c:c[0]); log.append((week,choice,money))
    s=scores(b,heard)
    value=min(s)
    if value>best[0]: best=(value,(s,log))
    if min(s)>=.8: break
print('Minimum',round(best[0]*100),'scores',[round(x*100) for x in best[1][0]])
for move in best[1][1]: print(move)
PY"
